mapper.select:
SELECT FROM t_product_vehicle v LEFT JOIN t_product p ON v.product_id = p.id WHERE 1 = 1
AND v.product_id = #{query.productId}
AND v.status = #{query.status}
AND v.vin LIKE CONCAT('%', #{query.vin}, '%')
ORDER BY v.update_time DESC, v.id DESC

SELECT COUNT(*)
FROM t_product_vehicle
WHERE product_id = #{productId}

mapper.insert:
INSERT INTO t_product_vehicle (
    product_id, vin, color, configuration, location, status,
    hold_type, source_type, source_id, hold_until,
    create_time, create_by, update_time, update_by
) VALUES (
    #{productId}, #{vin}, #{color}, #{configuration}, #{location}, #{status},
    #{holdType}, #{sourceType}, #{sourceId}, #{holdUntil},
    #{createTime}, #{createBy}, #{updateTime}, #{updateBy}
)

mapper.update:
UPDATE t_product_vehicle
SET status = 'AVAILABLE',
    hold_type = NULL,
    source_type = NULL,
    source_id = NULL,
    hold_until = NULL,
    update_time = #{updateTime},
    update_by = #{updateBy}
WHERE id = #{id}
  AND status = #{currentStatus}

UPDATE t_product_vehicle
SET status = 'OUTBOUND',
    hold_type = NULL,
    source_type = NULL,
    source_id = NULL,
    hold_until = NULL,
    update_time = #{updateTime},
    update_by = #{updateBy}
WHERE id = #{id}
  AND status = #{currentStatus}
